@Test
@Transactional
void 준영속_저장() {
    Item saved = itemRepository.save(new Item("A-4", "펜"));
    em.flush(); em.clear();

    Item detached = new Item("A-4", "굵은 펜");
    detached.setCreatedDate(saved.getCreatedDate());   // 등록일이 있다

    long n = counter.count(() -> itemRepository.save(detached));
    System.out.println("쿼리 " + n + "개");
}

