-- 플래그 방식

@Entity
public class Coupon implements Persistable<String> {

    @Id private String code;
    private String name;

    @Transient
    private boolean isNew = true;

    @Override public String getId() { return code; }
    @Override public boolean isNew() { return isNew; }

    @PostPersist
    @PostLoad
    void markNotNew() {
        this.isNew = false;
    }
}

@Test
@Transactional
void 플래그() {
    em.clear();
    long a = counter.count(() ->
            couponRepository.save(new Coupon("C-1", "쿠폰")));
    em.flush(); em.clear();

    Coupon loaded = couponRepository.findById("C-1").orElseThrow();
    System.out.println("조회한 것 새것? " + loaded.isNew());

    loaded.setName("바뀐 쿠폰");
    em.flush();
    System.out.println("저장 쿼리 " + a + "개");
}

