-- PostLoad 를 빼면

// @PostLoad 제거

@Test
@Transactional
void PostLoad_없이() {
    couponRepository.save(new Coupon("C-2", "쿠폰"));
    em.flush(); em.clear();

    Coupon loaded = couponRepository.findById("C-2").orElseThrow();
    System.out.println("조회한 것 새것? " + loaded.isNew());

    em.clear();
    Coupon detached = loaded;
    try {
        couponRepository.save(detached);
        em.flush();
    } catch (Exception e) {
        System.out.println("예외: " + e.getClass().getSimpleName());
    }
}

