-- 만 건을 다시 잰다

@Test
@Transactional
void 만_건() {
    long t = System.nanoTime();
    for (int i = 0; i < 10000; i++)
        itemRepository.save(new Item("I-" + i, "품목"));
    em.flush(); em.clear();
    System.out.printf("Persistable: %d ms%n",
            (System.nanoTime() - t) / 1_000_000);
}

