@Test
@Transactional
void 쿼리_수() {
    em.clear();
    long before = counter.count(() -> {
        for (int i = 0; i < 100; i++)
            plainItemRepository.save(new PlainItem("P-" + i, "품목"));
        em.flush();
    });
    em.clear();
    long after = counter.count(() -> {
        for (int i = 0; i < 100; i++)
            itemRepository.save(new Item("Q-" + i, "품목"));
        em.flush();
    });
    System.out.println("Persistable 없이: " + before + "개");
    System.out.println("Persistable 있고: " + after + "개");
}

